namespace ghidra.pcodeCPort.slghpatexpress;

using generic.stl;
using ghidra.pcodeCPort.slghsymbol;
using ghidra.pcodeCPort.slghsymbol;
using ghidra.sleigh.grammar;

// Pattern Equations ANDed together
public class EquationAnd : PatternEquation {

	private PatternEquation left;
	private PatternEquation right;

	public EquationAnd(Location location, PatternEquation l, PatternEquation r) : base(location)
    {
		(left = l).layClaim();
		(right = r).layClaim();
	}

	/* @Override */
	public void dispose() {
		base.release(left);
		base.release(right);
	}

	/* @Override */
	public void genPattern(VectorSTL<TokenPattern> ops) {
		left.genPattern(ops);
		right.genPattern(ops);
		setTokenPattern(left.getTokenPattern().doAnd(right.getTokenPattern()));
	}

	/* @Override */
	public void operandOrder(Constructor ct, VectorSTL<OperandSymbol> order) {
		left.operandOrder(ct, order); // List operands left
		right.operandOrder(ct, order); //  to right
	}

	/* @Override */
	public bool resolveOperandLeft(OperandResolve state) {
		int cur_rightmost = -1;			// Initially we don't know our rightmost
		int cur_size = -1;				//   or size traversed since rightmost
		bool res = right.resolveOperandLeft(state);
		if (!res) return false;
		if ((state.cur_rightmost != -1)&&(state.size != -1)) {
			cur_rightmost = state.cur_rightmost;
			cur_size = state.size;
		}
		res = left.resolveOperandLeft(state);
		if (!res) return false;
		if ((state.cur_rightmost == -1)||(state.size == -1)) {
			state.cur_rightmost = cur_rightmost;
			state.size = cur_size;
		}
		return true;
	}

}
